[tikz]
\begin{tikzpicture}[scale=0.8]
\usetikzlibrary{angles}
\coordinate (H) at (0,2);
\coordinate (J) at (1.5,0);
\coordinate (K) at (0,-3);
\coordinate (L) at (-1.5,0);
\draw (H)--(J)--(K)--(L)--cycle;
\node[above] at (H) {$H$};
\node[right] at (J) {$J$};
\node[below] at (K) {$K$};
\node[left] at (L) {$L$};
\pic[draw,angle radius=0.45cm] {angle = H--L--K};
\pic[draw,angle radius=0.55cm] {angle = H--L--K};
\pic[draw,angle radius=0.45cm] {angle = K--J--H};
\pic[draw,angle radius=0.55cm] {angle = K--J--H};
\end{tikzpicture}
[/tikz]
Which pair of equal angles is shown by the matching arcs?
